SELECT p.vote_id, p.user_id, u.username, u.nickname, u.avatar, p.choice FROM workspace_vote_participant p LEFT JOIN sys_user u ON u.id = p.user_id WHERE p.vote_id IN
#{voteId}
ORDER BY COALESCE(NULLIF(u.nickname, ''), u.username)

SELECT id, workspace_id, title, created_by, created_at
FROM workspace_vote
WHERE id = #{id}

SELECT vote_id, user_id, choice
FROM workspace_vote_participant
WHERE vote_id = #{voteId}
  AND user_id = #{userId}

mapper.update:
UPDATE workspace_vote_participant
SET choice = #{choice},
    voted_at = NOW()
WHERE vote_id = #{voteId}
  AND user_id = #{userId}
  AND choice IS NULL
